(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0026.js"] = [{"id":"glyph-seal-8005","script":"seal","character":"者","reading":"zhě","description":"zhě：(1)用在名词、动词、形容词、数词、词组后，并与其相结合，指人、指事、指物、指时等读～。作～。二～必居其一。来～。\n(2)助词，表示语气停顿并构成判断句的句式陈胜～，阳城人也。\n(3)这，此（多用在古诗词曲中）～个。～回。～番。～边走。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-者"},{"id":"glyph-seal-8006","script":"seal","character":"耆","reading":"qí；shì","description":"qí：(1)年老，六十岁以上的人～老。～年。～绅。～宿（sù）（指在社会上有名望的老年人）。\n(2)强横。\nshì：古同嗜”，爱好。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耆"},{"id":"glyph-seal-800b","script":"seal","character":"耋","reading":"dié","description":"dié：年老，七八十岁的年纪～期。耄～之年。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耋"},{"id":"glyph-seal-800c","script":"seal","character":"而","reading":"ér","description":"ér：(1)古同尔”，代词，你或你的～翁归，自与汝复算耳”。\n(2)连词（a.表平列，如多～杂”。b.表相承，如取～代之”。c.表递进，如～且”。d.表转折，如似是～非”。e.连接肯定和否定表互为补充，如浓～不烈”。f.连接状语和中心词表修饰，如侃侃～谈”。g.插在主语谓语中间表假设，如人～无信，不知其可”）。\n(3)表（从……到……）从上～下。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-而"},{"id":"glyph-seal-8010","script":"seal","character":"耐","reading":"nai；nài","description":"nài：(1)忍，受得住忍～。～久。～人寻味。\n(2)古同奈”，奈何。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耐"},{"id":"glyph-seal-8012","script":"seal","character":"耒","reading":"lěi","description":"lěi：古代称犁上的木把。\n〔～耜（sì）〕古代指耕地用的农具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耒"},{"id":"glyph-seal-8015","script":"seal","character":"耕","reading":"gēng","description":"gēng：用犁把土翻松～种（zhòng）。～作。～耘（耕地和除草，亦泛指劳动，如着意～～，自有收获”）。笔～（喻写文章）。舌～（喻教书）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耕"},{"id":"glyph-seal-8017","script":"seal","character":"耗","reading":"hào","description":"hào：(1)减损，消费～损。～费。～资。消～。\n(2)拖延～时间。\n(3)音信，消息噩～（人死的消息）。凶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耗"},{"id":"glyph-seal-8019","script":"seal","character":"耙","reading":"pá；bà","description":"bà：(1)把土块弄碎的农具。\n(2)用耙弄碎土块这块地～两遍了。\npá：(1)聚拢谷物或平土地用的用具～子。齿～。\n(2)用耙平整土地或聚拢谷物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耙"},{"id":"glyph-seal-8026","script":"seal","character":"耦","reading":"ǒu","description":"ǒu：(1)两个人在一起耕地。\n(2)同偶”②。\n〔～合〕物理学上指两个或两个以上的体系或两种运动形式之间通过各种相互作用而彼此影响以至联合起来的现象。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耦"},{"id":"glyph-seal-8028","script":"seal","character":"耨","reading":"nòu","description":"nòu：(1)古代锄草的农具。\n(2)锄草深耕易～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耨"},{"id":"glyph-seal-8033","script":"seal","character":"耳","reading":"ěr","description":"ěr：(1)听觉和平衡感觉的器官（通称耳朵”）～背（bèi）。～垂。～鬓厮磨（mó）。～穴。～聪目明。～濡目染。\n(2)像耳朵的东西木～。银～。\n(3)像耳朵一样分列两旁的东西～房。鼎～。\n(4)听说～闻。～软。～顺（指年至六十，听到别人的话，就能知道他的微妙的意思，后指人六十岁）。\n(5)文言助词，而已，罢了想当然～。\n(6)文言语气词（大致同矣”）且壮士不死则已，死即举大名～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耳"},{"id":"glyph-seal-8038","script":"seal","character":"耸","reading":"sǒng","description":"高起;矗立\n耸突出\n⒈高起，直立高～。～立。～入云霄。\n⒉惊动，震动～动。危言～听。～人听闻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耸"},{"id":"glyph-seal-803b","script":"seal","character":"耻","reading":"chǐ","description":"chǐ：羞愧，羞辱羞～。雪～。奇～大辱。～笑。～骂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耻"},{"id":"glyph-seal-803d","script":"seal","character":"耽","reading":"dān","description":"dān：(1)沉溺，入迷～乐。\n(2)迟延～误。～搁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耽"},{"id":"glyph-seal-803f","script":"seal","character":"耿","reading":"gěng","description":"gěng：(1)光明山头孤月～犹在，石上寒波晓更喧”。～～（a.光明，如～～星河”；b.形容忠诚，如忠心～～”；c.心里老想着不能忘，如～～于怀”）。\n(2)有骨气，刚正不阿～介。～直。～节（坚贞的节操）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耿"},{"id":"glyph-seal-8042","script":"seal","character":"聂","reading":"niè","description":"假借为摄”。握持\n古代地名\n聂zhé 1.切成薄片的肉。\n聂shè 1.\"摄\"的古字。握持。 2.惧怕。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聂"},{"id":"glyph-seal-8043","script":"seal","character":"聃","reading":"dān","description":"dān：(1)耳朵长而大～耳属肩。\n(2)古同耽”，沉溺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聃"},{"id":"glyph-seal-8046","script":"seal","character":"聆","reading":"líng","description":"líng：听～听。～取。～教（jiào）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聆"},{"id":"glyph-seal-804a","script":"seal","character":"聊","reading":"liáo","description":"liáo：(1)姑且，勉强，凑凑和和～且（姑且）。～以自娱。～复尔尔（姑且如此）。～备一格。\n(2)依赖，寄托无～。百无～赖。\n(3)略微～表寸心。\n(4)闲谈～天。闲～。\n(5)耳鸣～啾。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聊"},{"id":"glyph-seal-804b","script":"seal","character":"聋","reading":"lóng","description":"愚昧;不明事理","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聋"},{"id":"glyph-seal-804c","script":"seal","character":"职","reading":"zhí","description":"主管;任职\n尽职;称职\n⒈分内应做的或所担任的事情～务。～责。尽～。称～。\n⒉在工作中的位置或地位～位。～称。官～。在～。兼～。任要～。\n⒊掌管～掌。\n⒋旧时下属对上司的自称～遵命前去。\n⒌主要～由于此。\n⒍由于～此。～是之故。\n职tè 1.小木桩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-职"},{"id":"glyph-seal-8052","script":"seal","character":"聒","reading":"guō","description":"guō：声音吵闹，使人厌烦～耳。～噪。～～（话多的样子，如～～不停”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聒"},{"id":"glyph-seal-8054","script":"seal","character":"联","reading":"lián","description":"⒈连结，结合～结。～合。～珠。～盟。\n⒉对子，对联贴春～。送挽～。\n，以及国际友好关系，促进经济、文化、人道主义等方面的国际合作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-联"},{"id":"glyph-seal-8058","script":"seal","character":"聘","reading":"pìn","description":"pìn：(1)访问～问（古代指代表国家访问友邦）。通～。～使往来。\n(2)请人担任职务～书。～用。～请。招～。\n(3)定婚或女子出嫁～礼（彩礼）。～金。～姑娘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聘"},{"id":"glyph-seal-805a","script":"seal","character":"聚","reading":"jù；jv","description":"jù：会合，集合～合。～会。～积。～集。～谈。～拢。～齐。～餐。欢～一堂。物以类～。凝～。～沙成塔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聚"},{"id":"glyph-seal-8069","script":"seal","character":"聩","reading":"kuì","description":"先天性耳聋◇泛指耳聋\n昏聩,不明事理\n⒈耳聋或指先天性耳聋。\n⒉不明事理昏～。此人～ ～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聩"},{"id":"glyph-seal-806a","script":"seal","character":"聪","reading":"cōng","description":"明察。指耳闻声音而心能辨别其是真假\n聪明,有才智\n①听觉失～。\n②听觉灵敏耳～目明。\n【聪颖】聪明机灵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聪"},{"id":"glyph-seal-8071","script":"seal","character":"聱","reading":"áo","description":"áo：(1)话不顺耳～牙（语句念着不顺口）。\n(2)不听取他人的意见彼诮以为～者，为其不相从听”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聱"},{"id":"glyph-seal-807f","script":"seal","character":"聿","reading":"yù","description":"yù：(1)文言助词，无义，用于句首或句中。\n(2)古代称笔，用笔写文章。\n〔～皇〕轻疾的样子，如武骑～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聿"},{"id":"glyph-seal-8083","script":"seal","character":"肃","reading":"sù","description":"⒈恭敬～立。～然起敬。\n⒉严正，庄重～静。严～。\n肃xiāo 1.姓氏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肃"},{"id":"glyph-seal-8086","script":"seal","character":"肆","reading":"sì","description":"sì：(1)放纵，任意行事～口。～虐。～意。放～。～无忌惮。\n(2)尽，极～力（尽力）。～目。～勤。\n(3)陈列，陈设～筵。\n(4)古代指人处死刑后暴尸示众～诸市朝。\n(5)店铺市～。茶坊酒～。\n(6)四”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肆"},{"id":"glyph-seal-8087","script":"seal","character":"肇","reading":"zhào","description":"zhào：(1)开始，初始～始。～生。～端。～基（开始建立基础，打基础）。～造（开始建立）。\n(2)引发～事（a.引起事故；b.闲事）。～祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肇"},{"id":"glyph-seal-8089","script":"seal","character":"肉","reading":"ròu","description":"ròu：(1)人或动物体内红色、柔软的组织～体。～类。～食。肌～。～票（被盗匪掳去的人，盗匪借以向他的家属勒索钱财）。～身（佛教指肉体）。\n(2)果实中可以吃的部分桂圆～。冬瓜～厚。\n(3)果实不脆，不酥～瓤西瓜。\n(4)行动迟缓，性子慢做事真～。\n(5)古代称圆形物中有孔的边。\n(6)极亲密疼爱之称，多用呼子女。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肉"},{"id":"glyph-seal-808b","script":"seal","character":"肋","reading":"lèi；lē","description":"lèi：(1)胸部的两侧两～。～骨。～膜。\n(2)像肋骨的～木。\nlē：〔～脦〕衣裳肥大，不整洁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肋"},{"id":"glyph-seal-808c","script":"seal","character":"肌","reading":"jī","description":"jī：人或动物体内附着在骨头上或构成内脏的柔软物质，由许多纤维组成（通称肌肉”）～肤。～理。心～。随意～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肌"},{"id":"glyph-seal-8093","script":"seal","character":"肓","reading":"huāng","description":"huāng：中医指心下膈上的部位膏～（中国古代医学称心尖脂肪为膏”，心脏和膈膜之间为肓”，认为膏肓”是药力达不到的地方，所以病入～～”是指病重到无法医治了）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肓"},{"id":"glyph-seal-8096","script":"seal","character":"肖","reading":"xiāo；xiào","description":"xiāo：(1)衰微。\n(2)姓（萧”俗作肖”）。\nxiào：相似，像～像。不～。惟妙惟～。神情酷～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肖"},{"id":"glyph-seal-8098","script":"seal","character":"肘","reading":"zhǒu","description":"zhǒu：上臂与前臂相接处向外凸起的部分胳膊～儿。掣～（捉住其肘，喻阻挠别人做事）。～子（a.肘；b.指食品的猪腿上半部）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肘"},{"id":"glyph-seal-809d","script":"seal","character":"肝","reading":"gān","description":"gān：(1)人或动物体内最大的消化腺，有合成与贮存养料、分泌胆汁、解毒等功能～脏。～炎。～胆。～肠。心～。\n(2)中医学指五脏之一～火。～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肝"},{"id":"glyph-seal-80a0","script":"seal","character":"肠","reading":"cháng","description":"肠子或肠子制成的食品\n内心,情怀\n【肠断】形容极度悲伤忧愁。\n【肠肥脑满】见【脑满肠肥】。\n【肠骨】见【髂骨】。\n【肠管】肠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肠"},{"id":"glyph-seal-80a1","script":"seal","character":"股","reading":"gǔ","description":"gǔ：(1)大腿，自胯至膝盖的部分～骨。～肱（亦喻左右辅助得力的人）。\n(2)事物的分支或一部分（a.资金的一份，如～份”，～东”，～票”；b.机关团体中的一个部门；c.其他，如钗～”，八～文”）。\n(3)中国古代称不等腰三角形构成直角的较长的边。\n(4)量词（a.指成条的，如七～大水”；b.指气味，如一～香味”；c.指力气，如拧成一～劲”；d.批、部分，如一小～敌军”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-股"},{"id":"glyph-seal-80a2","script":"seal","character":"肢","reading":"zhī","description":"zhī：人的手、脚、胳膊、腿的统称，亦指某些动物的四条腿四～（指两手两脚）。～体。前～◇～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肢"},{"id":"glyph-seal-80a4","script":"seal","character":"肤","reading":"fū","description":"树木、果实的表皮\n某些像皮层那样的东西\n古代用于祭祀或供食用的肉类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肤"},{"id":"glyph-seal-80a5","script":"seal","character":"肥","reading":"féi","description":"féi：(1)含脂肪多的，与瘦”相对～肉。～胖。～缺（指收入多的官职）。～硕（a.大而肥胖；b.果实大而饱满）。～马轻裘。\n(2)土质含养分多的～沃。～美（a.肥沃；b.肥壮、丰美）。\n(3)能增加田地养分的东西（如粪、豆饼、化学配合剂等）～料。～力。\n(4)使田地增加养分～田。\n(5)指衣服鞋袜等宽大，与瘦”相对～大。～瘦儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肥"},{"id":"glyph-seal-80a9","script":"seal","character":"肩","reading":"jiān","description":"jiān：(1)脖子旁边胳膊上边的部分～膀。～胛。并～。\n(2)担负～负。～荷（hè）。～舆（轿子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肩"},{"id":"glyph-seal-80aa","script":"seal","character":"肪","reading":"fáng","description":"fáng：厚的脂膏，特指动物腰部肥厚的油脂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肪"},{"id":"glyph-seal-80ab","script":"seal","character":"肫","reading":"zhūn；chún","description":"zhūn：(1)禽类的胃（亦称胗”）鸡～。\n(2)诚恳、真挚～～。～笃。\nchún：(1)古代祭祀所用牲畜后体的一部分。\n(2)古同纯”，整体，全。\n(3)精细致密缪缪～～，其事不可循”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肫"},{"id":"glyph-seal-80af","script":"seal","character":"肯","reading":"kěn","description":"kěn：(1)许可，愿意首～（点头答应）。\n(2)骨头上附着的肉～綮（qīng）（筋骨结合的地方，喻重要的关键）。中（zhòng）～（喻言论正中要害）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肯"},{"id":"glyph-seal-80b1","script":"seal","character":"肱","reading":"gōng","description":"gōng：(1)胳膊由肘到肩的部分～骨。曲～两枕。\n(2)喻强大、得力的助手股～之臣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肱"},{"id":"glyph-seal-80b2","script":"seal","character":"育","reading":"yù","description":"yù：(1)生养～龄。节～。生儿～女。\n(2)养活～婴。哺～。培～。抚～。养～。\n(3)按照一定的目的长期地教导和训练德～。智～。体～。美～。教书～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-育"},{"id":"glyph-seal-80b4","script":"seal","character":"肴","reading":"yáo","description":"yáo：做熟的鱼肉等～馔。菜～。酒～。美酒佳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肴"},{"id":"glyph-seal-80ba","script":"seal","character":"肺","reading":"fèi","description":"fèi：人和某些高级动物的呼吸器官～脏。～病。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肺"},{"id":"glyph-seal-80be","script":"seal","character":"肾","reading":"shèn","description":"位于脊椎动物体腔内脊柱近旁的一对内脏器官,它排出尿液、尿酸和其它代谢的排泄物\n指外肾,即睾丸\n指性功能\n胃,沙囊,即肫","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肾"},{"id":"glyph-seal-80bf","script":"seal","character":"肿","reading":"zhǒng","description":"浮胀;肿胀","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肿"},{"id":"glyph-seal-80c1","script":"seal","character":"胁","reading":"xié","description":"⒈胸部的两侧，从腋下到肋骨尽处的部分两～。\n⒉恐吓，强迫威～。～迫。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胁"},{"id":"glyph-seal-80c2","script":"seal","character":"胂","reading":"shèn","description":"shèn：(1)有机化合物的一类，是砷化氢分子中的氢被羟基替换后生成的化合物。大多剧毒。\n(2)夹脊肉两～之上”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胂"},{"id":"glyph-seal-80c3","script":"seal","character":"胃","reading":"wèi","description":"wèi：(1)人和脊椎动物身体里主管消化食物的器官～脏。～液。～酸。～口（食欲，引申为兴趣、欲望。口”读轻声）。\n(2)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胃"},{"id":"glyph-seal-80c4","script":"seal","character":"胄","reading":"zhòu","description":"zhòu：(1)盔，古代战士戴的帽子甲～（甲衣和头盔）。介～（介”，甲衣）。\n(2)帝王或贵族的子孙贵～。～裔。～子（古代帝王和贵族的长子，都要进入国学学习，后亦泛称国子学生）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胄"},{"id":"glyph-seal-80c6","script":"seal","character":"胆","reading":"dǎn","description":"胆子,胆量,勇气\n勇胆猛\n①胆囊。\n②胆量～大心细。\n③装在某些器物内部用来容纳水、气等的东西暖瓶～。\n【胆大妄为】毫无顾忌地胡作非为。\n【胆矾】化学式cuso4·5h2o。蓝色晶体。易溶于水，在干燥空气中会逐渐风化，脱水时变为白色。有毒。可以制电池、颜料、媒染剂、杀虫剂。又称蓝矾。\n【胆固醇】醇的一种。白色结晶，质地软。人的胆汁、神经组织、血液中含量较高。在日光的紫外线作用下可转变为维生素.。是合成性激素的重要原料。胆固醇失调会引起动\n脉硬化和胆结石病。\n【胆寒】害怕；恐惧令人～。\n【胆绿素】胆汁内所含的一种色素。\n【胆略】胆量和智谋～过人。\n【胆落心寒】形容非肠怕。\n【胆囊】浓缩和贮存胆汁的器官。多数脊椎动物的胆囊由胆管扩大而成。人的胆囊近似长梨，长在肝脏右叶的下前方。又称胆、苦胆。\n【胆怯】胆量小；害怕。\n【胆识】胆量和见识～过人。\n【胆战心惊】形容十分害怕。又作心惊胆战。\n【胆汁】肝细胞分泌的一种外分泌液。黄绿色，味苦，弱碱性。贮存在胆囊中。能促进脂肪的分解、皂化和吸收。\n【胆汁质】一种气质类型。主要特征是外向，自我控制能力弱，行为敏捷但不一定稳健。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胆"},{"id":"glyph-seal-80cc","script":"seal","character":"背","reading":"bèi；bēi","description":"bèi：(1)人体后面从肩到腰的部分～脊。～包。～影。\n(2)物体的后面或反面～面。刀～。～后。～景。\n(3)用背部对着，与向”相对～光。人心向～。\n(4)向相反的方向～地性（植物向上生长的性质）。～道而驰。\n(5)避开，离开～地。～井离乡。\n(6)凭记忆读出～书。～诵。～台词。\n(7)违反违～。～离。～信弃义。\n(8)不顺～运。～兴（xìng）。\n(9)偏僻～静。\n(10)听觉不灵耳～。\n负；\n向；腹；\nbēi：人用背驮（tuó）东西，引申为负担～负。～包。～黑锅（喻受冤枉代人受过）。～包袱（喻有沉重的思想负担或经济负担）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-背"},{"id":"glyph-seal-80ce","script":"seal","character":"胎","reading":"tāi","description":"tāi：(1)人或其他哺乳动物母体内的幼体～儿。～生。～教（jiào）（指通过母体对胎儿施加影响，为胎儿发育提供良好的条件）。胚～。怀～。\n(2)事的开始，根源祸～。\n(3)器物的粗坯泥～。铜～。\n(4)衬在衣服、被褥面子和里子之间的东西棉花～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胎"},{"id":"glyph-seal-80d6","script":"seal","character":"胖","reading":"pàng；pán；pàn","description":"pàng：人体内含脂肪多～子。肥～。\n肥；\n瘦；\npán：安泰舒适心宽体～。\n肥；\n瘦；\npàn：古代祭祀用的半体牲司马升羊右～。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胖"},{"id":"glyph-seal-80d7","script":"seal","character":"胗","reading":"zhēn","description":"zhēn：鸟类的胃鸡～。鸭～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胗"},{"id":"glyph-seal-80d9","script":"seal","character":"胙","reading":"zuò","description":"zuò：(1)古代祭祀时供的肉。\n(2)福佑天地所～。”\n(3)古同祚”，指君位。\n(4)赐予～土（帝王以土地赐封功臣，酬其勋绩）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胙"},{"id":"glyph-seal-80da","script":"seal","character":"胚","reading":"pēi","description":"pēi：初期发育的生物体～芽。～囊。～胎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胚"},{"id":"glyph-seal-80dc","script":"seal","character":"胜","reading":"shèng","description":"言讫,?\n战胜,打败\n胜,克\n⒈赢，跟\"败\"、\"负\"相对～利。～仗。～不骄。\n⒊超过～过。～似。～于。略～一筹。\n⒋优美的，盛大的～地。～景。～会。\n①能担当得起或承受得住～任愉快。不～其烦。\n②尽不可～数。\n③又叫\"肽\"。见肽。\n胜xīng 1.同\"腥\"。 2.瘦。参见\"膌胜\"。\n胜qìng 1.见\"胜遇\"。\n胜shèng 1.能够承受，禁得起。 2.尽。 3.陵，欺凌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胜"},{"id":"glyph-seal-80dd","script":"seal","character":"胝","reading":"zhī","description":"zhī：〔胼～〕见胼”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胝"},{"id":"glyph-seal-80de","script":"seal","character":"胞","reading":"bāo","description":"bāo：同一父母所生的～兄。～妹。同～（ａ．同父母所生的；ｂ．同一个国家或民族的人）。～波（缅语同胞和亲戚的意思，缅甸人习惯用来称呼中国人，以表示亲切）。\n〔细～〕生物体的基本结构和功能单位，主要由细胞核、细胞质、细胞膜等构成，有运动、营养和繁殖等机能。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胞"},{"id":"glyph-seal-80e1","script":"seal","character":"胡","reading":"hú","description":"鸟兽颔下的垂肉或皮囊\n器物上下垂如胡的部分\n古代称北方和西方的民族如匈奴等为胡\n⒈〈古〉我国西北地区的民族之统称～人。～服。泛指我国少数民族的或外国的～椒。～琴。～萝卜。\n⒊文言疑问代词。什么，怎样～为慕大鲸？～不归？\n⒋〈古〉指兽颈下的垂肉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胡"},{"id":"glyph-seal-80e4","script":"seal","character":"胤","reading":"yìn","description":"yìn：后代～嗣（后嗣）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胤"},{"id":"glyph-seal-80e5","script":"seal","character":"胥","reading":"xū","description":"xū：(1)古代的小官～吏。钞～。\n(2)全，都万事～备。民～然矣。\n(3)蟹酱蟹～。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胥"},{"id":"glyph-seal-80e7","script":"seal","character":"胧","reading":"lóng","description":"胧lǒng 1.见\"胧肿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胧"},{"id":"glyph-seal-80ea","script":"seal","character":"胪","reading":"lú","description":"肚腹\n额头\n陈述\n报告\n⒉传达～传。\n⒊腹前。\n胪lǚ 1.祭名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胪"},{"id":"glyph-seal-80eb","script":"seal","character":"胫","reading":"jìng","description":"泛指人或禽兽的腿\n⒈小腿，自膝盖到脚跟的部分。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胫"},{"id":"glyph-seal-80ef","script":"seal","character":"胯","reading":"kuà","description":"kuà：腰和大腿之间的部分～裆。～骨。～下之辱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胯"},{"id":"glyph-seal-80f3","script":"seal","character":"胳","reading":"gē；gé","description":"gē：〔～臂〕上肢，肩膀以下手腕以上的部分。亦称胳膊”（臂”、膊”均读轻声）。\n〔～肢窝〕同夹肢窝”。\ngé：同骼”。\n〔～肢〕在别人身上抓挠，使人由发痒而笑（肢”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胳"},{"id":"glyph-seal-80f6","script":"seal","character":"胶","reading":"jiāo","description":"古代大学之称,后泛指学校\n鸡鸣声,泛指禽类鸣声\n⒈粘性物质。用动物皮、角或树脂等制成。也有人工合成的牛皮～。树脂～。万能～。\n⒉制成胶质的药品阿～。鹿角～。\n⒊特指橡胶～轮。～底鞋。\n⒋像胶那样有粘性的～泥。～水。\n⒌粘住，粘合～着。～合。\n胶jiǎo 1.见\"胶胶扰扰\"。\n胶háo 1.戾。参见\"胶加\"﹑\"胶戾\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胶"},{"id":"glyph-seal-80f8","script":"seal","character":"胸","reading":"xiōng","description":"xiōng：身体前面颈下腹上的部分，借指心里～脯。～膛。～腔。～口。～骨。～椎。～膜。～怀（抱负、气量）。～襟（同胸怀”）。～无点墨（指读书太少，文化水平极低）。直抒～臆。～中有数（shù）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胸"},{"id":"glyph-seal-80fd","script":"seal","character":"能","reading":"néng；nài","description":"néng：(1)才干，本事～力。～耐。才～。\n(2)有才干的～人。～手。贤～。～工巧匠。～者为师。\n(3)胜任，善于～够。～柔～刚。力所～及。欲罢不～。～动。\n(4)会（表示可能性）小弟弟～走路了。\n(5)应该你不～这样说他。\n(6)物理学名词，能量”的简称电～。热～。\n(7)和睦（萧）何素不与曹参相～”。\n(8)传说中的一种兽，似熊。\n(9)古代称一种三足鳖。\nnài：古同耐”，受得住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-能"},{"id":"glyph-seal-8102","script":"seal","character":"脂","reading":"zhī","description":"zhī：(1)动物体内或油料植物种子内的油质～肪。～膏。松～。～油。香～。\n(2)指胭脂”～粉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脂"},{"id":"glyph-seal-8106","script":"seal","character":"脆","reading":"cuì","description":"cuì：(1)容易断，容易碎的～性。～枣。～骨。青～爽口。～生生。～弱。\n(2)声音清爽（高音）～亮。～美。清～悦耳。\n(3)说话做事爽利痛快干～。办事很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脆"},{"id":"glyph-seal-8109","script":"seal","character":"脉","reading":"mài","description":"mài：(1)分布在人和动物周身内的血管～络。～理。\n(2)动脉的跳动～搏。切～（中医指诊脉）。～口（中医切脉的部位）。～息。～象（指脉搏的形象与动态）。～门（手腕部可以看到的桡动脉跳动的部分）。诊～。\n(3)像血管那样连贯而自成系统的东西山～。叶～。矿～。～～相承。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脉"},{"id":"glyph-seal-810a","script":"seal","character":"脊","reading":"jǐ","description":"jǐ：(1)人和动物背上中间的骨头～椎。～髓。～柱。～梁。～背。～椎动物。\n(2)中间高起的部分山～。屋～。书～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脊"},{"id":"glyph-seal-810d","script":"seal","character":"脍","reading":"kuài","description":"把鱼、肉切成薄片\n脍炙人口","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脍"},{"id":"glyph-seal-8113","script":"seal","character":"脓","reading":"nóng","description":"腐烂\n肥硕\n同醲”。浓厚。特指浓烈的酒","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脓"},{"id":"glyph-seal-8114","script":"seal","character":"脔","reading":"luán","description":"量词。用于块状的鱼肉\n切肉成块\n⒈切成小块的肉吃一～。\n⒉分割，切碎～割。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脔"},{"id":"glyph-seal-8118","script":"seal","character":"脘","reading":"wǎn","description":"wǎn：胃的内部胃～（中医指胃内部的空腔）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脘"},{"id":"glyph-seal-811a","script":"seal","character":"脚","reading":"jiǎo","description":"jiǎo：(1)人和某些动物身体最下部接触地面的部分～心。～掌。～背。～跟。～步。～印。～法（指踢球、踢毽等的技巧）。～镣。～踏实地（形容做事实事求是，不浮夸）。\n(2)最下部～注。山～。墙～。\n(3)剩下的废料，渣滓下～料。\n(4)旧时指与体力搬运有关的～夫。～行（háng）。～钱。拉～。\n〔～本〕表演戏剧或拍摄影视所依据的底本。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脚"},{"id":"glyph-seal-812c","script":"seal","character":"脬","reading":"pāo","description":"pāo：(1)膀胱尿（suī）～。\n(2)量词，用于屎尿一～屎。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脬"},{"id":"glyph-seal-812f","script":"seal","character":"脯","reading":"pú；fǔ","description":"fǔ：(1)肉干鹿～。兔～。\n(2)水果蜜渍后晾干的成品果～。杏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脯"},{"id":"glyph-seal-8131","script":"seal","character":"脱","reading":"tuō","description":"tuō：(1)离开，落掉～产。～发（fà）。～节。～离。～落。～贫（摆脱贫困）。～稿（完成著作）。～手。摆～。挣～。临阵逃～。\n(2)遗漏～漏。～误。～文（因抄刊古书而误脱的字。亦称夺文”）。\n(3)取下，除去～下。～帽。～氧。～脂。～胎换骨。\n(4)倘若，或许～有不测。\n(5)轻慢～略（放任，不拘束）。～易（轻率，不讲究礼貌）。轻～（轻率，不持重，放荡）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脱"},{"id":"glyph-seal-813e","script":"seal","character":"脾","reading":"pí","description":"pí：(1)人和动物内脏之一，在胃的左下侧，是重要的贮藏血液的器官和最大的淋巴器官～脏。\n(2)中医学指五脏之一～胃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-脾"},{"id":"glyph-seal-8146","script":"seal","character":"腆","reading":"tiǎn","description":"tiǎn：(1)丰厚，美好。\n(2)胸部或腹部挺出～着胸脯。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腆"},{"id":"glyph-seal-814a","script":"seal","character":"腊","reading":"là","description":"农历十二月\n腊后花期知渐近,寒梅已作东风信\n⒈干肉，将肉晾干。\n腊liè 1.剑的两面刃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腊"},{"id":"glyph-seal-814c","script":"seal","character":"腌","reading":"yān","description":"yān：用盐浸渍食物～肉。～菜。～制。～渍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腌"},{"id":"glyph-seal-8150","script":"seal","character":"腐","reading":"fǔ","description":"fǔ：(1)朽烂，变质～烂。～朽。～败。～化。～蚀。～臭。陈～。流水不～。\n(2)思想陈旧过时～旧。～儒。迂～。\n(3)某些豆制食品豆～（腐”读轻声）。～乳。～竹。\n(4)古代指施以宫刑～刑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腐"},{"id":"glyph-seal-8153","script":"seal","character":"腓","reading":"féi","description":"féi：(1)胫骨后的肉。亦称腓肠肌”，俗称腿肚子”。\n(2)覆庇，倚庇牛羊～字之。”\n(3)草木枯萎百卉具～。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腓"},{"id":"glyph-seal-8154","script":"seal","character":"腔","reading":"qiāng","description":"qiāng：(1)动物身体中空的部分～子。体～。满～热血。\n(2)器物的中空部分炉～。\n(3)乐曲的调子～调（diào）。唱～。梆子～。\n(4)说话的声音、语调开～。京～。装～作势。拿～拿调。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腔"},{"id":"glyph-seal-8165","script":"seal","character":"腥","reading":"xīng","description":"xīng：(1)像鱼的气味～气。血～。～膻。～秽。～臭。～臊。～风血雨。\n(2)鱼或肉一类的食品荤～。\n(3)生肉君赐～，必熟而蔫之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腥"},{"id":"glyph-seal-8171","script":"seal","character":"腱","reading":"jiàn","description":"jiàn：一种连接肌肉和骨骼的由结缔组织所构成的纤维束或膜，色白，质地坚韧肌～。～鞘。～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腱"},{"id":"glyph-seal-8174","script":"seal","character":"腴","reading":"yú","description":"yú：(1)腹下的肥肉桀纣之君，垂～尺余。”\n(2)肥胖丰～。\n(3)土地肥沃膏～。～润。\n(4)丰裕。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腴"},{"id":"glyph-seal-8179","script":"seal","character":"腹","reading":"fù","description":"fù：(1)一般指人和脊椎动物躯干的一部分，介于胸和骨盆之间，包括腹壁”、腹腔”及内脏（通常称肚子”）～部。～膜。～水。～泻。～疾。心～（喻极亲近的人）。～稿。～诽（指口里不说而心里不以为然。亦作腹非”）。遗～子。\n(2)喻地区的前部、内部或中部～地。～背受敌。\n(3)厚（冬季之月）冰方盛，水泽～坚，命取冰。”\n(4)怀抱出入～我。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腹"},{"id":"glyph-seal-817b","script":"seal","character":"腻","reading":"nì","description":"粘糊\n亲昵\n细腻\n厌烦\n见了别\n⒈食品油脂过多油～。肥肉太多，～人。\n⒉滋润，光滑细～。滑～。\n⒊因过多而厌烦～烦。看～了。耍～了。\n⒋污垢尘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腻"},{"id":"glyph-seal-817c","script":"seal","character":"腼","reading":"miǎn","description":"miǎn：〔～腆〕害羞，不自然，如小孩见了生人有点～～”。亦作靦觕”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腼"},{"id":"glyph-seal-817e","script":"seal","character":"腾","reading":"téng","description":"奔驰\n跳跃\n⒈跳跃虎～。～跃。\n⒉奔驰奔～。\n⒊上升～空。飞～。\n⒋乘，骑～驴。\n⒌传，传递～书信。\n⒍使空出来～时间。～出一间房子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-腾"},{"id":"glyph-seal-8180","script":"seal","character":"膀","reading":"bǎng","description":"bǎng：(1)胳膊的上部靠肩的部分～臂。肩～。～阔腰圆。\n(2)鸟类和昆虫的飞行器官翅～。～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膀"},{"id":"glyph-seal-8182","script":"seal","character":"膂","reading":"lǚ","description":"⒈脊梁骨背～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膂"},{"id":"glyph-seal-818a","script":"seal","character":"膊","reading":"bó","description":"bó：(1)上肢，近肩的部分胳～。赤～（光膀子）。\n(2)分裂尸体而曝之杀而～诸城上”。\n〔厚～〕厚切肉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膊"},{"id":"glyph-seal-818f","script":"seal","character":"膏","reading":"gāo；gào","description":"gāo：(1)肥，肥肉～粱（肥肉、细粮）。～腴。～沃。\n(2)脂油春雨如～。～泽（ａ．滋润作物的及时雨；ｂ．喻给予恩惠）。\n(3)中医指心尖脂肪，认为是药力达不到的部位病入～肓。\ngào：(1)把油抹在车轴或机械上～油。\n(2)把毛笔蘸上墨汁在砚台边上掭～笔。～墨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膏"},{"id":"glyph-seal-8198","script":"seal","character":"膘","reading":"biāo","description":"biāo：肥肉（多指牲畜）～肥。～壮。上～。落～。～满肉肥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膘"},{"id":"glyph-seal-819c","script":"seal","character":"膜","reading":"mó","description":"mó：(1)动植物体内像薄皮的组织肋～。耳～。黏～。苇～。\n(2)像膜的薄皮牛奶表面结了一层薄～。\n〔～拜〕跪在地上高举双手虔诚地行礼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膜"},{"id":"glyph-seal-81b3","script":"seal","character":"膳","reading":"shàn","description":"shàn：(1)饭食～食。用～。～宿。\n(2)进食宰夫～稻于梁西”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膳"},{"id":"glyph-seal-81ba","script":"seal","character":"膺","reading":"yīng","description":"yīng：(1)胸义愤填～。\n(2)接受，承当～选（当选）。～赏。～受。荣～。\n(3)讨伐，打击～惩。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膺"},{"id":"glyph-seal-81bb","script":"seal","character":"膻","reading":"shān；dàn","description":"shān：像羊肉的气味～气。～味。腥～。\ndàn：(1)袒露。\n(2)胸中～中（ａ．中医指胸腔中央，心包所在处；ｂ．针炙穴位名，位于前胸部正中）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-膻"},{"id":"glyph-seal-81c2","script":"seal","character":"臂","reading":"bì；bei","description":"bì：从肩到手腕的部分～力。～腕。～肘。左膀右～。助你一～之力。\nbei：〔胳～〕见胳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臂"},{"id":"glyph-seal-81c6","script":"seal","character":"臆","reading":"yì","description":"yì：(1)胸胸～（心里，多指心里的话或想法，如直抒～～”）。\n(2)主观地，缺乏客观依据的～造。～测。～度（duó）。～断。～见。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臆"},{"id":"glyph-seal-81ca","script":"seal","character":"臊","reading":"sào；sāo","description":"sāo：像尿或狐狸的气味～气。腥～↑～。\nsào：害羞害～。羞～。\n〔～气〕倒霉（气”读轻声）。\n〔～子〕方言，肉末或肉丁，如羊肉～～面”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臊"},{"id":"glyph-seal-81e3","script":"seal","character":"臣","reading":"chén","description":"chén：(1)君主时代的官吏，有时亦包括百姓～僚。～子。～服。君～。\n(2)官吏对君主的自称王必无人，～愿奉璧往使。”\n(3)古人谦称自己。\n(4)古代指男性奴隶～仆。～虏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臣"},{"id":"glyph-seal-81e7","script":"seal","character":"臧","reading":"zāng；zàng；cáng","description":"zāng：(1)善，好～否（pǐ）（褒贬，评论，说好说坏）。\n(2)古代对奴仆的贱称～获。\n(3)古同赃”，赃物。\n(4)姓。\nzàng：(1)古同藏”，储放东西的地方。\n(2)古同脏”，身体的内部器官。\ncáng：古同藏1”，收存。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臧"},{"id":"glyph-seal-81ea","script":"seal","character":"自","reading":"zì","description":"zì：(1)本人，己身～己。～家。～身。～白。～满。～诩。～馁。～重（zhòng）。～尊。～谦。～觉（jué）。～疚。～学。～圆其说。～惭形秽。～强不息。\n(2)从，由～从。～古以来。\n(3)当然～然。～不待言。～生～灭。放任～流。\n(4)假如～非圣人，外宁必有内忧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-自"},{"id":"glyph-seal-81ec","script":"seal","character":"臬","reading":"niè","description":"niè：(1)箭靶子。\n(2)古代测日影的标杆。\n(3)标准，法式圭～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臬"},{"id":"glyph-seal-81ed","script":"seal","character":"臭","reading":"chòu；xiù","description":"chòu：(1)不好闻的气味，与香”相对～味儿。～氧。恶～。\n(2)香气左佩刀，右备容～，烨然若神人”。\n(3)惹人厌恶的～钱。～美。～架子。～名远扬。\n(4)狠狠地～骂一通。\n(5)指子弹、炮弹坏，失效～火。\n香；\nxiù：(1)气味的总称无声无～。\n(2)同嗅”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臭"},{"id":"glyph-seal-81f3","script":"seal","character":"至","reading":"zhì","description":"zhì：(1)到～此。自始～终。从古～今。～于。以～。甚～。\n(2)极、最～少。～亲。～交（最相好的朋友）。～诚。～高无上。～理名言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-至"},{"id":"glyph-seal-81f4","script":"seal","character":"致","reading":"zhì","description":"zhì：(1)送给，给予～仕（退休）。～辞。～电。～力。～哀。～命。\n(2)招引，使达到～病。～使。以～。专心～志。\n(3)意态，情况大～。别～。景～。兴（xìng）～。\n(4)细密，精细～密。精～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-致"},{"id":"glyph-seal-81fb","script":"seal","character":"臻","reading":"zhēn","description":"zhēn：(1)达到日～完善。\n(2)到，来到百福并～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臻"},{"id":"glyph-seal-81fc","script":"seal","character":"臼","reading":"jiù","description":"jiù：(1)舂米的器具，用石头或木头制成，中间凹下。\n(2)形状像臼的～齿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臼"},{"id":"glyph-seal-81fe","script":"seal","character":"臾","reading":"yú","description":"yú：〔须～〕见须”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-臾"},{"id":"glyph-seal-8200","script":"seal","character":"舀","reading":"yǎo","description":"yǎo：用瓢、勺等取东西（多指流体）～水。～汤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舀"},{"id":"glyph-seal-8202","script":"seal","character":"舂","reading":"chōng","description":"chōng：把东西放在石臼或乳钵里捣掉皮壳或捣碎～米。～药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舂"},{"id":"glyph-seal-8204","script":"seal","character":"舄","reading":"xì","description":"xì：(1)鞋。\n(2)同潟”。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舄"},{"id":"glyph-seal-8205","script":"seal","character":"舅","reading":"jiù","description":"jiù：(1)母亲的弟兄～～。～父。～母。\n(2)妻的弟兄妻～。\n(3)古代称丈夫的父亲～姑（公婆）。昔者吾～死于虎”。\n(4)古代帝王称异姓大邦诸侯为伯舅”，异姓蓄诸侯为叔舅”。诸侯亦称异姓大夫为舅”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舅"},{"id":"glyph-seal-8206","script":"seal","character":"舆","reading":"yú","description":"车辆,尤指马车\n轿子\n①车箱。\n②车。\n③指载柩车。\n④轿子。\n⑤制作车箱的工匠。\n⑥古代职位低贱的吏卒。\n⑦特指驾车的人。\n⑧抬;扛。\n⑨运载。\n舆2 yù通\"誉\"。名誉;荣誉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舆"},{"id":"glyph-seal-820c","script":"seal","character":"舌","reading":"shé","description":"shé：(1)人或动物嘴里辨别滋味、帮助咀嚼和发音的器官～头。～耕（ａ．指读书勤奋；ｂ．旧时学者授徒，依口说谋生，好像农夫耕田得粟）。唇枪～剑。\n(2)语言辩论的代称～战（激烈议论）。\n(3)像舌头的东西帽～。火～。\n(4)铃或释中的锤。\n(5)指箭靶两旁上下伸出的部分。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舌"},{"id":"glyph-seal-820d","script":"seal","character":"舍","reading":"shě；shè","description":"shè：(1)居住的房子宿～。旅～。校～。\n(2)居住，休息～于山麓。\n(3)谦辞，多指亲属中比自己年纪小或辈分低的～弟。～侄。～亲。\n(4)古代行军一宿或三十里为一舍退避三～（喻对人让步）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舍"},{"id":"glyph-seal-8210","script":"seal","character":"舐","reading":"shì","description":"舐shì舔～糠及米（〈喻〉先占地方再夺政权）。老牛～犊（犊小牛。〈喻〉爱子女）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舐"},{"id":"glyph-seal-8212","script":"seal","character":"舒","reading":"shū","description":"shū：(1)展开，伸展～展。～畅。～张。～卷（juǎn）。～适。～心。\n(2)从容，缓慢～缓。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舒"},{"id":"glyph-seal-821b","script":"seal","character":"舛","reading":"chuǎn","description":"chuǎn：(1)错误，错乱～错（ａ．错误；ｂ．意外的事；ｃ．参差不齐，交错）。～驳。命途多～。\n(2)违背～迕。伦常乖～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舛"},{"id":"glyph-seal-821c","script":"seal","character":"舜","reading":"shùn","description":"shùn：(1)传说中的上古帝王尧～（传说均是上古的贤明君主，后泛指圣人）。尧天～日（喻太平盛世）。\n(2)木槿”的别称颜如～华（喻女子容貌美丽）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舜"},{"id":"glyph-seal-821e","script":"seal","character":"舞","reading":"wǔ","description":"wǔ：(1)按一定的节奏转动身体表演各种姿势～蹈。～技。～姿。～会。～剑。～女。～曲。～台。\n(2)耍弄～弊。～文弄墨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舞"},{"id":"glyph-seal-821f","script":"seal","character":"舟","reading":"zhōu","description":"zhōu：船～辑。龙～。轻～。一叶扁～。泛～。同～共济。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舟"},{"id":"glyph-seal-822a","script":"seal","character":"航","reading":"háng","description":"háng：(1)船。\n(2)行船或飞行～海。～空。～天。～行（xíng）。～班。民～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-航"},{"id":"glyph-seal-822b","script":"seal","character":"舫","reading":"fǎng","description":"fǎng：船画～。游～。石～。～楼（船楼）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舫"},{"id":"glyph-seal-822c","script":"seal","character":"般","reading":"bān","description":"bān：(1)样，种，类这～。那～。百～。～配。暴风雨～的掌声。\n(2)古同班”，散布，分布。\n(3)同搬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-般"},{"id":"glyph-seal-8238","script":"seal","character":"舸","reading":"gě","description":"gě：大船百～争流。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舸"},{"id":"glyph-seal-8239","script":"seal","character":"船","reading":"chuán","description":"chuán：水上交通工具～舶。～只。～舱。～帆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-船"},{"id":"glyph-seal-823b","script":"seal","character":"舻","reading":"lú","description":"舳舻。大船","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-舻"},{"id":"glyph-seal-8247","script":"seal","character":"艇","reading":"tǐng","description":"tǐng：(1)轻便的小船游～。汽～。\n(2)某些大船潜水～。鱼雷～。舰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艇"},{"id":"glyph-seal-826e","script":"seal","character":"艮","reading":"gèn","description":"gèn：(1)八卦之一，代表山。\n(2)古代指时辰若依然葬书，多用乾、～二时，并是近半夜，此即文与礼违。”\n(3)指东北方～维。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艮"},{"id":"glyph-seal-826f","script":"seal","character":"良","reading":"liáng","description":"liáng：(1)好～好。善～。～辰美景。～知～能（中国古代唯心主义哲学家指人类不学而知的、不学而能的、先天具有的判断是非与善恶的能力）。～莠不齐。\n(2)很～久。～多趣味。用心～苦。\n(3)诚然，的确古人秉烛夜游，～有以也”。以为犬～我友”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-良"},{"id":"glyph-seal-8270","script":"seal","character":"艰","reading":"jiān","description":"艰难;困难\n⒉〈古〉指父丧或母丧丁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艰"},{"id":"glyph-seal-8272","script":"seal","character":"色","reading":"sè","description":"sè：(1)由物体发射、反射的光通过视觉而产生的印象颜～。～彩。～相（xiàng）。～调（diào）。\n(2)脸上表现出的神气、样子脸～。气～。～厉内荏。\n(3)情景，景象行～匆匆。景～宜人。\n(4)种类各～用品。\n(5)品质，质量音～。成～。足～纹银。\n(6)妇女美貌姿～。～艺。\n(7)情欲～情∶（hào）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-色"},{"id":"glyph-seal-8273","script":"seal","character":"艳","reading":"yàn","description":"文辞华丽\n⒈长得漂亮美而～。\n⒉色彩鲜明，文辞华美～丽。鲜～。百花争～。信言不～。\n⒊喜爱，羡慕～羡。\n⒋指爱情方面的事～史。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艳"},{"id":"glyph-seal-827d","script":"seal","character":"艽","reading":"jiāo；qiú","description":"qiú：(1)远荒～野。\n(2)禽兽巢穴中的垫草禽兽有～，人民有室”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艽"},{"id":"glyph-seal-827e","script":"seal","character":"艾","reading":"ài","description":"ài：(1)多年生草本植物，嫩叶可食，老叶制成绒，供针灸用～子。～蒿。～绒。\n(2)止，绝方兴未～。\n(3)美好少（shào）～（年轻美好的女子）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艾"},{"id":"glyph-seal-827f","script":"seal","character":"艿","reading":"nǎi","description":"nǎi：〔芋～〕见芋”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-艿"},{"id":"glyph-seal-8282","script":"seal","character":"节","reading":"jié","description":"节骨眼，节骨眼儿\n榞枅祵溃樬蕩畧?\n做工作要抓住节骨眼儿,别乱抓一气\n节子\n⒉见jié。\n⒈植物茎上分枝长叶的部位。特指竹节枝～。〈引〉人或动物的骨节肘关～。\n⒉时节，季节寒暑易～。〈引〉节日春～。八一建军～。十一国庆～。重阳～。\n⒊礼度礼～。\n⒋事项，事物的分段情～。章～。\n⒌音乐、舞蹈中有规律的强弱、长短、快慢等的表现～奏。～拍。\n⒍省减，限制，管辖～约。～制生育。这个兵团归他～制。〈引〉择要摘取～录几条。～译本。\n⒐〈古〉使臣出使外国时所持的凭证符～。旌～◇称出使外国的人为\"使节\"。\n⒑量词两～课。四～电池。五～火车。\n⒒一种用竹编的古乐器击～。\n⒓航行速度单位，符号kn，1节=1浬/时。\n⒔船舰划分锚链的长度单位，1节=2.5米锚链。\n⒖见jiē。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-节"},{"id":"glyph-seal-8284","script":"seal","character":"芄","reading":"wán","description":"wán：〔～兰〕多年蔓生草本植物，断之有白汁，可食。叶对生，心脏形。花白色，有紫色斑点。茎、叶和种子均可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芄"},{"id":"glyph-seal-828a","script":"seal","character":"芊","reading":"qiān","description":"qiān：〔～～〕草木茂盛。\n〔～绵〕草木茂盛。亦作芊眠”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芊"},{"id":"glyph-seal-828b","script":"seal","character":"芋","reading":"yù","description":"yù：(1)多年生草本植物，作一年生栽植培。地下有肉质的球茎，含淀粉很多，可供食用，亦可药用。俗称芋奶”、芋艿”、芋头”。\n(2)指马铃薯”洋～。\n(3)指甘薯”山～。\n(4)指荸荠”乌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芋"},{"id":"glyph-seal-828d","script":"seal","character":"芍","reading":"sháo","description":"sháo：〔～药〕多年生草本植物，羽状复叶，小叶卵形或披针形。夏初开大花，供观赏，根可入药。简称芍”，如赤芍”、白芍”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芍"},{"id":"glyph-seal-828e","script":"seal","character":"芎","reading":"xiōng","description":"xiōng：〔～??（qióng）〕多年生草本植物，羽状复叶，白色，果实椭圆形。产于中国四川和云南省。全草有香气，地下茎可入药。亦称川芎”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芎"},{"id":"glyph-seal-8291","script":"seal","character":"芑","reading":"qǐ","description":"qǐ：(1)梁、黍一类的农作物。\n(2)类似苦菜的一种草本植物薄言采～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芑"},{"id":"glyph-seal-8292","script":"seal","character":"芒","reading":"máng","description":"máng：(1)某些禾本科植物种子壳上的细刺针尖对麦～。初露锋～。\n(2)像芒的东西光～。\n(3)多年生草本植物，叶细长有尖，叶除可作绿篱和布置庭园外，又可作造纸原料和编织草鞋，嫩叶可做牛的饲料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芒"},{"id":"glyph-seal-8297","script":"seal","character":"芗","reading":"xiāng","description":"谷香\n用以调味的香草\n⒈气味好闻，味道鲜美，跟\"臭\"相对～气。～花。稻谷～。饭菜～。\n⒉指有香味的东西～水。檀～。洗发～波。\n⒊舒适，受欢迎睡得可～。这批货上市～得很。\n⒋〈古〉指一种香草，可用于调味。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芗"},{"id":"glyph-seal-8299","script":"seal","character":"芙","reading":"fú","description":"fú：〔～蓉〕ａ．落叶灌木，花有红、黄、白各色，别于荷花，亦称木芙蓉”；ｂ．荷花的别称。\n〔～蕖〕荷花的别称。\n〔～蓉城〕中国四川省成都市的别称，简称蓉城”或蓉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芙"},{"id":"glyph-seal-829c","script":"seal","character":"芜","reading":"wú","description":"杂乱\n⒈荒废～城。田园荒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芜"},{"id":"glyph-seal-829d","script":"seal","character":"芝","reading":"zhī","description":"zhī：〔灵～〕见灵”。\n〔～兰〕芝”和兰”，古书上指两种香草，喻德行的高尚或友情、环境的美好等，如～～之室”、～～玉树”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芝"},{"id":"glyph-seal-829f","script":"seal","character":"芟","reading":"shān","description":"shān：割草，引申为除去～草。～除（ａ．除草；ｂ．删削文字）。～夷。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芟"},{"id":"glyph-seal-82a1","script":"seal","character":"芡","reading":"qiàn","description":"qiàn：(1)一年生水草，茎叶有刺，亦称鸡头”～实（芡的果实；种子的仁可食，经碾磨制成淀粉。亦称鸡头米”）。～粉。\n(2)烹调时用淀粉加水调成的浓汁勾～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芡"},{"id":"glyph-seal-82a5","script":"seal","character":"芥","reading":"jiè；gài","description":"jiè：小草，喻轻微纤细的事物草～。纤～。～舟。\n〔～菜〕一年或二年生草本植物，种子黄色，味辛辣，磨成粉末，称芥末”，作调味品。按用途分为叶用芥菜（如雪里蕻”）；茎用芥菜（如榨菜”）；根用芥菜（如大头菜”）。\ngài：〔～菜〕一年生草本植物，芥（jiè）菜的变种，叶大，表面多皱纹，叶脉显著，可食。亦作盖菜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芥"},{"id":"glyph-seal-82a6","script":"seal","character":"芦","reading":"lú","description":"lú：姓。\n〔～苇〕多年生草本植物，多生于水边，茎中空，茎可编席，亦可造纸。简称芦”，如～花”、～根”、～笛”、～席”、～荡”；亦简称苇”，如～丛”、～塘”、～箔”、～荡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芦"},{"id":"glyph-seal-82a8","script":"seal","character":"芨","reading":"jī","description":"jī：〔白～〕多年生草本植物，根茎供药用。亦作白及”。\n〔～～草〕多年生草本植物，生于碱性草滩上。茎和叶是造纸和制人造丝的原料，亦可编织筐、篓、席等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芨"},{"id":"glyph-seal-82a9","script":"seal","character":"芩","reading":"qín","description":"qín：古书上指芦苇一类的植物。\n〔黄～〕多年生草本植物，叶对生，花淡紫色，或带青白色，根长大，色深黄，可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芩"},{"id":"glyph-seal-82aa","script":"seal","character":"芪","reading":"qí","description":"qí：〔黄～〕多年生草本植物，茎横卧地上，根可入药。亦作黄耆”。\n〔～母〕多年生草本植物，叶细长，花淡紫色，亦称知母”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芪"},{"id":"glyph-seal-82ab","script":"seal","character":"芫","reading":"yuán；yán","description":"yuán：〔～花〕落叶灌木，开紫色小花，有毒；供观赏，花蕾可入药。\nyán：〔～荽〕一年生或二年生草本植物，叶和茎有特殊香气，可用来调味；果实球形，亦有香气，用做香料，亦可入药。俗称香菜”，亦称胡荽”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芫"},{"id":"glyph-seal-82ac","script":"seal","character":"芬","reading":"fēn","description":"fēn：花草的香气～芳。清～。～香。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芬"},{"id":"glyph-seal-82ae","script":"seal","character":"芮","reading":"ruì","description":"ruì：(1)絮。\n(2)系盾的绶带。\n(3)小的样子。\n(4)草生的样子～～。\n(5)中国周代诸侯国名，在今陕西省大荔县。\n(6)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芮"},{"id":"glyph-seal-82b3","script":"seal","character":"芳","reading":"fāng","description":"fāng：(1)花草的香气～香。～草。～菲（ａ．花草的香气；ｂ．指花草）。～馥。～馨。芬～。\n(2)喻美好的～名。～龄（年龄，用于少女）。～姿（美好的姿态，用于少女）。～邻（关系融洽的邻居，用作敬辞）。流～百世。\n(3)花卉群～竞艳。～时（花盛时节）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芳"},{"id":"glyph-seal-82b8","script":"seal","character":"芸","reading":"yún","description":"芸yùn 1.花草枯黄貌。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芸"},{"id":"glyph-seal-82b9","script":"seal","character":"芹","reading":"qín","description":"qín：菜名，一年或二年生草本植物，茎可食。亦称水芹”。还有一种草芹”，有特殊香味，俗称药芹”。\n〔～献〕对人谦称所赠东西不好。亦称献芹”。\n〔～意〕谦辞，微薄的情意。\n〔～藻〕古代喻贡士或有才学之士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芹"},{"id":"glyph-seal-82bc","script":"seal","character":"芼","reading":"mào","description":"芼mào 1.择取。 2.杂;拌和。 3.通\"毛\"。草。指可供食用的野菜或水草。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芼"},{"id":"glyph-seal-82bd","script":"seal","character":"芽","reading":"yá","description":"yá：(1)植物的幼体，可以发育成茎、叶或花的那一部分发～。嫩～。幼～。萌～。豆～。\n(2)形状像芽的东西肉～（伤口愈合后多长出的肉）。银～（银矿苗）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-芽"},{"id":"glyph-seal-82c7","script":"seal","character":"苇","reading":"wěi","description":"芦苇，多年生草本植物，常生长在水边。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-82cb","script":"seal","character":"苋","reading":"xiàn","description":"苋属植物的泛称\n苋菜\n苋wǎn 1.见\"苋尔\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苋"},{"id":"glyph-seal-82cc","script":"seal","character":"苌","reading":"cháng","description":"即苌楚\n①苌楚，古书上说的一种植物。\n②姓。\n【苌弘化碧】苌弘的血化作了碧玉。形容精诚。苌弘，又称苌叔，春秋时周大夫。神话传说苌弘被杀后，其血三年化为碧玉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苌"},{"id":"glyph-seal-82cd","script":"seal","character":"苍","reading":"cāng","description":"灰白色\n满面尘灰烟火色,两鬓苍苍十指黑。╠\n①青色～松。\n②灰白色，面色～白。\n③姓。\n【苍白】\n②形容缺乏旺盛的生命力～无力。\n①灰白色两鬓～。\n②苍茫天～，野茫茫。\n【苍黄】见【仓黄】。\n【苍凉】悲凉。\n【苍茫】空阔辽远；无边无际暮色～。\n【苍莽】苍茫。\n【苍穹】天空。又作穹苍。\n【苍生】古时指老百姓。\n【苍术】菊科，多年生草本植物。花白色或淡红色。其根茎含挥发油及较多量的维生素a、b，有健胃作用。分布于我国浙江、江苏、安徽等省。\n苍cǎng 1.见\"苍莽\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苍"},{"id":"glyph-seal-82cf","script":"seal","character":"苏","reading":"sū；sù","description":"sù：朝向～刃者死”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苏"},{"id":"glyph-seal-82d1","script":"seal","character":"苑","reading":"yuàn","description":"yuàn：(1)古代养禽兽植林木的地方，多指帝王的花园鹿～。御～。～囿。\n(2)学术、文艺荟萃之处文～。艺～。学～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苑"},{"id":"glyph-seal-82d3","script":"seal","character":"苓","reading":"líng","description":"líng：(1)指茯苓”。\n(2)古书上说的一种植物。\n(3)古同零”，零落。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苓"},{"id":"glyph-seal-82d5","script":"seal","character":"苕","reading":"tiáo；sháo","description":"tiáo：(1)古书上指凌霄花。\n(2)指苇子的花。\n〔～子〕一年生或二年生草本植物，茎细长，羽状复叶，花紫色，可作绿肥。亦称野豌豆”。\nsháo：〔红～〕甘薯的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苕"},{"id":"glyph-seal-82d7","script":"seal","character":"苗","reading":"miáo","description":"miáo：(1)初生的植物或没有秀穗的庄稼禾～。麦～。树～。幼～。～子（亦喻继承某种事业的接班人）。～而不秀（只长苗而不秀穗，喻本身条件虽好，但没有成就）。\n(2)形状像苗的火～儿。\n(3)某些初生的饲养的动物鱼～。\n(4)能使机体产生免疫力的微生物制剂疫～。卡介～。\n(5)子孙后代～裔。\n(6)中国少数民族，主要分布于贵州、湖南、云南、四川、湖北等省和广西壮族自治区～族。～绣。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苗"},{"id":"glyph-seal-82db","script":"seal","character":"苛","reading":"kē；hē","description":"kē：(1)过于严厉～刻。～毒。～求。～责。～待。\n(2)繁重，使人难以忍受～重（zhòng）。～捐杂税。\n(3)腐蚀性～性（如氢氧化钾、氢氧化钠等能腐蚀皮肤及纤维之类的化学性质）。～性钠（烧碱）。\nhē：古同诃”，谴责，责问。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苛"},{"id":"glyph-seal-82dc","script":"seal","character":"苜","reading":"mù","description":"mù：〔～蓿〕多年生草本植物，叶子长圆形，花紫色，结荚果，可以喂牲口，做肥料。嫩苗可食。亦作目宿”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苜"},{"id":"glyph-seal-82de","script":"seal","character":"苞","reading":"bāo","description":"bāo：(1)花托下面像叶的小片花～。～片‖～待放。\n(2)茂盛竹～松茂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苞"},{"id":"glyph-seal-82df","script":"seal","character":"苟","reading":"gǒu","description":"gǒu：(1)姑且，暂且～安。～延残喘。～且。\n(2)马虎，随便～得。～合。不敢～同。\n(3)如果，假使～非其人。～富贵，无相忘”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苟"},{"id":"glyph-seal-82e1","script":"seal","character":"苡","reading":"yǐ","description":"yǐ：〔薏～〕见薏”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苡"},{"id":"glyph-seal-82e3","script":"seal","character":"苣","reading":"jù；qǔ；jv","description":"jù：用苇杆扎成的火炬。\n〔莴～〕见莴”。\n〔～胜〕胡麻的别称。\nqǔ：〔～卖菜〕多年生草本植物，野生，叶互生，广披针形，花黄色，茎叶嫩时可食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苣"},{"id":"glyph-seal-82e5","script":"seal","character":"若","reading":"ruò；rě","description":"ruò：(1)如果，假如～果。倘～。假～。天～有情天亦老。\n(2)如，像年相～。安之～素。旁～无人。置～罔闻。门庭～市。\n(3)你，汝～辈。更～役，复～赋，则何如？”\n(4)约计～干（gān）。～许。\n(5)此，如此以～所为，求～所欲，犹缘木而求鱼也。”\n(6)顺从曾孙是～。”\n(7)指海若”（古代神话中的海神）望洋向～而叹。”\n(8)指若木”（古代神话中的树名）。\n(9)指杜若”（古书上说的一种香草）沐兰泽，含～芳”。～英（杜若”的花）。\n(10)文言句首助词，常与夫”合用～夫阴雨霏霏，连月不开。”\n(11)用在形容词或副词后，表示事物的状态桑之未落，其叶沃～”。\nrě：〔般（bō）若〕见般3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-若"},{"id":"glyph-seal-82e6","script":"seal","character":"苦","reading":"kǔ","description":"kǔ：(1)像胆汁或黄连的滋味，与甘”相对甘～。～胆。～瓜。\n(2)感觉难受的～境。～海（原为佛教用语，后喻很苦的环境）。～闷‖辛茹～。吃～耐劳。～恼。\n(3)为某种事所苦～雨。～旱。～夏。～于（ａ．对某种情况感到苦脑；ｂ．表示相比之下更苦些）。\n(4)有耐心地，尽力地～劝。～口婆心。刻～。～心孤诣。\n(5)使受苦那件事可～了你啦！","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苦"},{"id":"glyph-seal-82eb","script":"seal","character":"苫","reading":"shān；shàn","description":"shān：草帘子，草垫子草～子。\nshàn：用席、布等遮盖车上～块塑料布。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苫"},{"id":"glyph-seal-82f1","script":"seal","character":"英","reading":"yīng","description":"yīng：(1)花落～缤纷。\n(2)才能出众，才能出众的人～俊。群～荟萃。～才。～雄。～烈。\n(3)精华，事物最精粹的部分精～。～华‖～咀华。\n(4)用羽毛做的矛饰二矛重（chóng）～。\n(5)古同瑛”，似玉的美石。\n(6)指英国”～文。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-英"},{"id":"glyph-seal-82f4","script":"seal","character":"苴","reading":"jū；chá；jv","description":"jū：(1)大麻的雌珠，开花后能结果实。\n(2)鞋里垫的草。\nchá：浮草，枯草如彼栖～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苴"},{"id":"glyph-seal-82f7","script":"seal","character":"苷","reading":"gān","description":"gān：(1)甘草。\n(2)甙的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苷"},{"id":"glyph-seal-82f9","script":"seal","character":"苹","reading":"píng；pēng","description":"pēng：〔～萦〕回旋的样子，如争湍～～，汨活澎濞”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-苹"},{"id":"glyph-seal-8300","script":"seal","character":"茀","reading":"fú","description":"草木茂盛；也有遮蔽、阻塞等义。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8301","script":"seal","character":"茁","reading":"zhuó","description":"zhuó：(1)植物才生长出来的样子。\n(2)壮盛，壮健～壮。～实（实”读轻声）。～长（zhǎng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茁"},{"id":"glyph-seal-8302","script":"seal","character":"茂","reading":"mào","description":"mào：(1)草木旺盛～盛。丰～。\n(2)美，有才德～士。～才（即秀才”）。\n(3)有机化合物，环戊间二烯的简称。无色液体，用来制农药、塑料等。\n(4)古同懋”，勉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茂"},{"id":"glyph-seal-8303","script":"seal","character":"范","reading":"fàn","description":"假借为筪。法则\n典范\n模子\n⒈铸造器物的模子铜～。钱～。\n⒉楷模，榜样模～。典～。师～。示～表演。\n⒊一定的界限，限制～围。防～。就～。\n【范畴】\n①类型，范围此鱼属于鲫鱼～畴。\n②高度概括的基本概念。如化合、分解是化学的～畴；商品、价值是政治经济学的～畴；矛盾、质和量等是哲学的～畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-范"},{"id":"glyph-seal-8304","script":"seal","character":"茄","reading":"qié；jia","description":"qié：〔～子〕一年生草本植物，花紫色。果实一般为紫色，也有白色或绿色的，可食，如拌～泥”。\n〔番～〕一年生草本植物，花黄色。果实圆形，熟时红、黄色。亦称西红柿”，可食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茄"},{"id":"glyph-seal-8305","script":"seal","character":"茅","reading":"máo","description":"máo：多年生草本植物，春季先开花，后生叶，花穗上密生白毛。根茎可食，亦可入药。叶可编蓑衣（亦称白茅”）～草。～庐。～舍。名列前～（喻名次列在前面）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茅"},{"id":"glyph-seal-8306","script":"seal","character":"茆","reading":"máo","description":"máo：(1)同茅”。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茆"},{"id":"glyph-seal-830e","script":"seal","character":"茎","reading":"jīng","description":"柱;竿\n小枝\n器物的柄\n指长\n⒈植物的营养器官之一。它常是植物的主干，起支撑作用，又具有输送水分、养料和储存养料等作用。有些植物有地下茎，如藕、马铃薯、荸荠等，还可发生变态及进行无性繁\n殖。\n⒉量词，义同\"根\"几～麦秆。数～毛发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茎"},{"id":"glyph-seal-830f","script":"seal","character":"茏","reading":"lóng","description":"形容草木青翠茂盛。也作葱茏”\n茏葱\n茏lǒng 1.见\"笼茸\"﹑\"笼苁\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茏"},{"id":"glyph-seal-8311","script":"seal","character":"茑","reading":"niǎo","description":"寄生木\n⒈古书上所说的一种小灌木，茎能攀缘别的树木。\n①一年生蔓草。\n②茑和女萝。〈喻〉亲戚关系。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茑"},{"id":"glyph-seal-8314","script":"seal","character":"茔","reading":"yíng","description":"埋葬\n茔地","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茔"},{"id":"glyph-seal-8315","script":"seal","character":"茕","reading":"qióng","description":"回旋着飞\n孤独,无兄弟\n悲愁\n⒈没有弟兄，孤独～独。\n⒊忧愁。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茕"},{"id":"glyph-seal-8317","script":"seal","character":"茗","reading":"míng","description":"míng：(1)茶树的嫩芽。\n(2)茶香～。品～。～具。煮～。\n(3)古同酩”，酩酊。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茗"},{"id":"glyph-seal-831c","script":"seal","character":"茜","reading":"qiàn","description":"qiàn：红色～纱。～衫。～裙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茜"},{"id":"glyph-seal-8327","script":"seal","character":"茧","reading":"jiǎn","description":"许多昆虫幼虫在化蛹前包围身体大部分的由丝组成的外皮,在其中化蛹。家蚕的茧是商业蚕丝的来源\n指茧丝\n絮丝棉的衣服\n通趼”。手掌或脚掌等部因摩擦而生成的硬皮\n形状如茧的\n⒈某些昆虫的幼虫在变成蛹之前吐丝或分泌某种物质做成的壳。家蚕、柞蚕和蓖麻蚕等的茧是缫丝的原料蚕～。家蚕～子。卖蚕～儿。\n⒉手、脚上因劳动、走路等摩擦而生的硬皮脚底有老～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茧"},{"id":"glyph-seal-8328","script":"seal","character":"茨","reading":"cí","description":"cí：(1)用茅或苇覆盖房子茅～（用茅草覆盖屋顶）。～宇（茅屋）。～檐。～门。\n(2)蒺藜～藿（藿”，野菜；指以茨藿充饥，引申为粗劣的食物）。\n(3)积土填满～其所决而高之。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茨"},{"id":"glyph-seal-832c","script":"seal","character":"茬","reading":"chá","description":"chá：(1)庄稼收割后余留在地里的短茎和根～子。麦～。\n(2)同一块田地上庄稼种植或收割的次数头～。\n(3)短而硬的头发、胡子胡～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茬"},{"id":"glyph-seal-832d","script":"seal","character":"茭","reading":"jiāo","description":"jiāo：(1)喂牲畜的干草峙乃刍～”。\n(2)用竹篾或芦苇编成的缆索。\n〔～白〕菰的嫩茎经某种病菌寄生后膨大，可做蔬菜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茭"},{"id":"glyph-seal-832f","script":"seal","character":"茯","reading":"fú","description":"fú：〔～苓〕寄生在松树根上的一种块状菌类植物，皮黑色，有皱纹，内部白色或粉红色；包含松根的称茯神”，均可入药，亦可食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茯"},{"id":"glyph-seal-8331","script":"seal","character":"茱","reading":"zhū","description":"zhū：〔～萸〕ａ．落叶小乔木，结长椭圆形核果，红色，味酸，可入药。通称山茱萸”；ｂ．落叶乔木，果实红色，可入药。通称吴茱萸”；ｃ．落叶乔木，枝上有刺，羽状复叶，果实红色、球形，可入药，可提制芳香油。通称食茱萸”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茱"},{"id":"glyph-seal-8335","script":"seal","character":"茵","reading":"yīn","description":"yīn：铺垫的东西，垫子、褥子、毯子的通称～褥。～席。～饪（寝褥和烹饪，引申为睡眠和饮食）。绿草如～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茵"},{"id":"glyph-seal-8338","script":"seal","character":"茸","reading":"róng","description":"róng：(1)草初生纤细柔软的样子绿～～的草地。\n(2)细柔的毛、发半脱紫～裘”。～毛。\n(3)指鹿茸”（带细毛的才生出来的鹿角，可入药）～客（指鹿）。参（shēn）～（指人参和鹿茸）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茸"},{"id":"glyph-seal-8339","script":"seal","character":"茹","reading":"rú","description":"rú：(1)吃，引申为忍受～素。～荤。～痛（忍痛）‖辛～苦（原意吃苦辣的东西，引申为忍受辛苦）。～古涵今（接受、包含古今的所有知识）。\n(2)臭，败以～鱼去蝇，蝇愈至，不可禁”。\n(3)柔软柔～而寡断。\n(4)菜菜～有畦”。\n(5)根互相牵连的样子拔茅～”。\n(6)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-茹"},{"id":"glyph-seal-8340","script":"seal","character":"荀","reading":"xún","description":"xún：(1)传说中的一种香草。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荀"},{"id":"glyph-seal-8343","script":"seal","character":"荃","reading":"quán","description":"quán：(1)古书上说的一种香草，亦用以喻国君～察（旧时书信中请人原谅的敬辞，荃不察余之中情兮”）。～鉴。～宰（喻君臣）。\n(2)古同筌”，捕鱼的竹器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荃"},{"id":"glyph-seal-8346","script":"seal","character":"荆","reading":"jīng","description":"jīng：(1)落叶灌木，叶有长柄，掌状分裂，开蓝紫色小花，枝条可编筐篮等（亦称楚”）紫～。～条。～棘。披～斩棘。\n(2)古代用荆条做的刑仗负～请罪。\n(3)中国古代九州”之一，春秋时楚国别称～州。～璞（喻美质、未经任用的卓越人才）。\n(4)旧时对人谦称自己的妻子拙～。山～。～妻。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荆"},{"id":"glyph-seal-8347","script":"seal","character":"荇","reading":"xìng","description":"xìng：〔～菜〕多年生草本植物，叶略呈圆形，浮在水面，根生水底，夏天开黄花；结椭圆形蒴果。全草可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荇"},{"id":"glyph-seal-8349","script":"seal","character":"草","reading":"cǎo","description":"cǎo：(1)对高等植物中除了树木、庄稼、蔬菜以外的茎干柔软的植物的统称；广义指茎干比较柔软的植物，包括庄稼和蔬菜青～。野～。茅～。水～。花～。～鞋。～堂（茅草盖的堂屋，旧时文人以此自称山野间的住所，有自谦卑陋的意思）。～原。～坪。～行露宿。～菅人命。\n(2)特指用作燃料、饲料的稻麦之类的茎叶～料。柴～。稻～。\n(3)粗糙，不细致～率（shuài）。～鄙（粗野朴陋）。～具（粗劣的食物）。\n(4)汉字的一种书体～书。～字（亦为旧时谦称自己的别名）。章～（草书的一种，笔画保存了一些隶书的笔势，因其最初用于奏章，故名章草”）。狂～。～体（ａ．指汉字草书；ｂ．拼音文字的手写体，有大草、小草之分）。\n(5)打稿子，亦指稿子；引申为初步的，非正式的～拟。～诏（为皇帝草拟诏书）。\n(6)荒野，原野，引申为在野的、民间的～野。～莽。～寇。～贼。\n(7)雌性的（用于某些家畜、家禽）～鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-草"},{"id":"glyph-seal-834f","script":"seal","character":"荏","reading":"rěn","description":"rěn：(1)一年生草本植物，茎方形，叶椭圆形，有锯齿，开白色小花，种子通称苏子”，可榨油；嫩叶可食。亦称白苏”。\n(2)柔，软弱～弱。～染（柔弱的样子）。色厉内～。\n(3)古同戎”、壬”，大。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荏"},{"id":"glyph-seal-8350","script":"seal","character":"荐","reading":"jiàn","description":"再;又;接连\n⒈介绍，推举推～能人。举～贤人。\n⒉动物能吃的草鹿食～。\n⒊草席，草垫。〈引〉垫～鞋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荐"},{"id":"glyph-seal-8351","script":"seal","character":"荑","reading":"yí","description":"yí：割除田里的野草，引申为削平芟～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荑"},{"id":"glyph-seal-8352","script":"seal","character":"荒","reading":"huāng","description":"huāng：(1)年成不好，收成不好～年。灾～。防～。备～。\n(2)长满野草，或无人耕种～芜。～地。开～。\n(3)废弃～废。～疏。～置。业精于勤，～于嬉。\n(4)冷落偏僻～村。～郊。～落（luò）（ａ．荒凉冷落；ｂ．荒疏衰退）。～颓。\n(5)严重缺乏，不够用煤～。\n(6)不实在的，不正确的～信。～唐（ａ．浮夸，不实在；ｂ．行为放荡。唐”均读轻声）。\n(7)放纵，迷乱～淫。～腆（沉湎于酒）。\n(8)远，边远的地方～远。～遐。八～。\n(9)扩大天作高山大王～之”。\n(10)包有奄有龟蒙，遂～大东，至于海邦”。\n(11)工业上指没有经过精细加工的～子（毛坯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荒"},{"id":"glyph-seal-8354","script":"seal","character":"荔","reading":"lì","description":"lì：〔～枝〕ａ．常绿乔木，果实球形，果实外壳有瘤状突起，熟时紫红色，果肉白色半透明，多汁，味甜美；ｂ．这种植物的果实。均亦称离枝”、丹荔”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荔"},{"id":"glyph-seal-835a","script":"seal","character":"荚","reading":"jiá","description":"某些树木的翅果","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荚"},{"id":"glyph-seal-835f","script":"seal","character":"荟","reading":"huì","description":"聚集\n遮掩;隐翳\n⒈草木茂盛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荟"},{"id":"glyph-seal-8360","script":"seal","character":"荠","reading":"qí；ji","description":"指荠菜\n荠麦青青。\n荠菜\n见荸荠” qi\n⒈荠菜，一年生或二年生草本，春季开白花，果实为短角果。茎叶嫩时可吃。全草可供药用。\n⒉见qí。\n荠cí 1.蒺藜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荠"},{"id":"glyph-seal-8361","script":"seal","character":"荡","reading":"dàng","description":"动;摇动;震动\n清除\n①摇动；摆动动～、飘～。\n②无事走来走去；闲～。\n③清洗～涤。\n④清除全部弄光；扫～。\n⑤放纵；行为不检点放～。\n⑥浅水湖芦苇～。\n【荡涤】冲洗；清除。\n【荡气回肠】见【回肠荡气】。\n【荡然】形容原有的东西完全消失～无存。\n荡tàng 1.量词。\n荡tāng 1.古水名。即今之汤水，在河南省汤阴县北境。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荡"},{"id":"glyph-seal-8363","script":"seal","character":"荣","reading":"róng","description":"草本植物的花。又为花的通称\n飞檐,屋檐两头翘起的部分\n⒈草开花，草的花或谷类结穗草～。无叶无～。黍～。\n⒉茂盛，兴盛欣欣向～。繁～富强。\n⒊光荣，受人 敬重～誉。～耀。～军。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荣"},{"id":"glyph-seal-8364","script":"seal","character":"荤","reading":"hūn","description":"指鸡、鸭、鱼、肉等食物。与素”相对\n⒈肉食～菜。吃～。\n⒉有特殊气味的蔬菜，如葱、蒜等～辛。五～。\n⒊粗俗，下流全是～话。\n荤xūn 1.见\"荤粥\"﹑\"荤允\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荤"},{"id":"glyph-seal-8365","script":"seal","character":"荥","reading":"yíng","description":"荥经 ying\n⒈荥经县，在四川省。\n⒉见xíng㈡。\n荥yīng 1.见\"荥瀯\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荥"},{"id":"glyph-seal-8366","script":"seal","character":"荦","reading":"luò","description":"古地名\n明显,分明\n荦荦大端\n⒈杂色的牛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荦"},{"id":"glyph-seal-8367","script":"seal","character":"荧","reading":"yíng","description":"萤火\n眩惑\n⒈微弱的光亮。\n⒉使人目眩。\n①火星。\n②迷惑～惑人心。\n荧xíng 1.水名。故址在今河南省郑州市西北。\n荧jiǒng 1.药草名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荧"},{"id":"glyph-seal-8368","script":"seal","character":"荨","reading":"qián","description":"荨麻疹 xun\n荨tán 1.同\"\"。 2.通\"燂\"。火势上腾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荨"},{"id":"glyph-seal-8369","script":"seal","character":"荩","reading":"jìn","description":"荩草\n烧剩的柴木。也泛指剩余的事物。通烬”\n通进”。进用◇引申为忠诚\n⒈荩草，一年生草本，茎细，花灰绿或带紫色。茎可编器物，茎与叶可做黄色染料，茎的纤维可用于造纸。\n⒉忠诚～臣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荩"},{"id":"glyph-seal-836a","script":"seal","character":"荪","reading":"sūn","description":"古书中记载的一种香草。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-836b","script":"seal","character":"荫","reading":"yīn","description":"日影\n指地窖或暗室\n⒈阳光被遮，又凉又潮树～。那间房很～。\n⒉遮盖榆柳～后簷。\n⒊保佑，庇护庇～。\n⒋封建时代帝王给予有官爵大臣的子孙读书或做官等之特权封赏。\n荫yīn 1.树荫。 2.日影。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荫"},{"id":"glyph-seal-836f","script":"seal","character":"药","reading":"yào","description":"⒈治病的物品中～。开～方。～物治疗。\n⒉有某些作用的化学物品火～。炸～。农～。消毒～。\n⒊治疗无可救～。\n药shuò 1.热貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-药"},{"id":"glyph-seal-8377","script":"seal","character":"荷","reading":"hé","description":"hé：即莲”。\n〔～包〕ａ．佩戴的小囊；ｂ．食品名。\n〔～尔蒙〕激素”的旧称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荷"},{"id":"glyph-seal-837c","script":"seal","character":"荼","reading":"tú；shu","description":"tú：(1)古书上说的一种苦菜～毒（荼”是苦菜，毒”指毒虫毒蛇之类，喻毒害，如～～生灵”）。\n(2)古书上指茅草的白花如火如～。\n(3)古同涂”，涂炭。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-荼"},{"id":"glyph-seal-8386","script":"seal","character":"莆","reading":"pú","description":"pú：姓。\n〔～田〕地名，在中国福建省。\n〔～仙戏〕中国福建地方戏曲剧种之一，流行于莆田，游仙县一带。亦称兴化戏”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莆"},{"id":"glyph-seal-838e","script":"seal","character":"莎","reading":"shā；suō","description":"suō：〔～草〕多年生草本植物，地下的块根称香附子”，可入药。\nshā：多用于人名、地名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莎"}];
